/* Default Theme - Auto-generated from tweakcn */

/* Light mode */
[data-theme="default-light"] {
  --background: hsl(300 50% 100%);
  --foreground: hsl(300 0% 3.94%);
  --card: hsl(300 50% 100%);
  --card-foreground: hsl(300 0% 3.94%);
  --popover: hsl(300 50% 100%);
  --popover-foreground: hsl(300 0% 3.94%);
  --primary: hsl(330 0% 9.05%);
  --primary-foreground: hsl(0 0% 98.03%);
  --secondary: hsl(300 0% 96.06%);
  --secondary-foreground: hsl(330 0% 9.05%);
  --muted: hsl(300 0% 96.06%);
  --muted-foreground: hsl(300 0% 45.15%);
  --accent: hsl(300 0% 96.06%);
  --accent-foreground: hsl(330 0% 9.05%);
  --destructive: hsl(354.09 99.92% 44.64%);
  --destructive-foreground: hsl(300 50% 100%);
  --border: hsl(330 0% 89.82%);
  --input: hsl(330 0% 89.82%);
  --ring: hsl(300 0% 63.02%);
  --chart-1: hsl(211.8 99.99% 78.65%);
  --chart-2: hsl(217.41 91.37% 59.58%);
  --chart-3: hsl(221.43 86.37% 54.06%);
  --chart-4: hsl(223.66 78.72% 47.86%);
  --chart-5: hsl(226.54 70.01% 39.92%);
  --sidebar: hsl(0 0% 98.03%);
  --sidebar-foreground: hsl(300 0% 3.94%);
  --sidebar-primary: hsl(330 0% 9.05%);
  --sidebar-primary-foreground: hsl(0 0% 98.03%);
  --sidebar-accent: hsl(300 0% 96.06%);
  --sidebar-accent-foreground: hsl(330 0% 9.05%);
  --sidebar-border: hsl(330 0% 89.82%);
  --sidebar-ring: hsl(300 0% 63.02%);
  --font-sans: ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, 'Noto Sans', sans-serif, 'Apple Color Emoji', 'Segoe UI Emoji', 'Segoe UI Symbol', 'Noto Color Emoji';
  --font-serif: ui-serif, Georgia, Cambria, "Times New Roman", Times, serif;
  --font-mono: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace;
  --radius: 0.625rem;
  --shadow-x: 0;
  --shadow-y: 1px;
  --shadow-blur: 3px;
  --shadow-spread: 0px;
  --shadow-opacity: 0.1;
  --shadow-color: hsl(0 0% 0%);
  --shadow-2xs: 0 1px 3px 0px hsl(0 0% 0% / 0.05);
  --shadow-xs: 0 1px 3px 0px hsl(0 0% 0% / 0.05);
  --shadow-sm: 0 1px 3px 0px hsl(0 0% 0% / 0.10), 0 1px 2px -1px hsl(0 0% 0% / 0.10);
  --shadow: 0 1px 3px 0px hsl(0 0% 0% / 0.10), 0 1px 2px -1px hsl(0 0% 0% / 0.10);
  --shadow-md: 0 1px 3px 0px hsl(0 0% 0% / 0.10), 0 2px 4px -1px hsl(0 0% 0% / 0.10);
  --shadow-lg: 0 1px 3px 0px hsl(0 0% 0% / 0.10), 0 4px 6px -1px hsl(0 0% 0% / 0.10);
  --shadow-xl: 0 1px 3px 0px hsl(0 0% 0% / 0.10), 0 8px 10px -1px hsl(0 0% 0% / 0.10);
  --shadow-2xl: 0 1px 3px 0px hsl(0 0% 0% / 0.25);
  --tracking-normal: 0em;
  --spacing: 0.25rem;
}

